func partitionLabels(s string) []int {
    // 每个字符最后出现的位置
    lastIndex := [26]int{}
    for i, ch := range s {
        lastIndex[ch-'a'] = i
    }

    var res []int
    start, end := 0, 0
    for i, ch := range s {
        if lastIndex[ch-'a'] > end {
            end = lastIndex[ch-'a']
        }
        if i == end {
            res = append(res, end-start+1)
            start = end + 1
        }
    }
    return res
}
